545	TEST_CASE("L24: resume restores mepc/mcause/mtval/mip/mie via abstract "
546	          "commands, each carrying its drained value on DATA0/DATA1")
547	{
548	  RecordingBus bus;
549	  bus.dmstatus_value = (1u << 9) | (1u << 17);
550	
551	  auto s = rv64_state(0x80001000, 0);
552	  s.mepc   = 0x1111111122222222ULL;
553	  s.mcause = 0x8000000000000007ULL;  // machine timer interrupt cause encoding
554	  s.mtval  = 0x3333333344444444ULL;
555	  s.mip    = 0x0000000000000080ULL;  // MTIP
556	  s.mie    = 0x0000000000000888ULL;  // MTIE | MEIE | MSIE
557	
558	  hybrid::ResumeDriver driver(bus, kScratch);
559	  driver.resume(s);
560	
561	  // Each CSR gets a write-COMMAND (bit 16 set) carrying its value on the
562	  // DATA0/DATA1 written immediately before (same shape as fcsr/mscratch).
563	  const std::pair<uint16_t, uint64_t> want[] = {
564	    {0x341, s.mepc}, {0x342, s.mcause}, {0x343, s.mtval},
565	    {0x344, s.mip},  {0x304, s.mie},
566	  };
567	  for (const auto& [csr, val] : want) {
568	    std::optional<std::size_t> cmd_idx;
569	    for (std::size_t i = 0; i < bus.ops.size(); ++i) {
570	      const auto& op = bus.ops[i];
571	      if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
572	          && (op.value & 0xFFFFu) == hybrid::regno_csr(csr)
573	          && ((op.value >> 16) & 1u)) {
574	        cmd_idx = i;
575	        break;
576	      }
577	    }
578	    REQUIRE(cmd_idx.has_value());
579	    REQUIRE(*cmd_idx >= 2);
580	    const auto& d0 = bus.ops[*cmd_idx - 2];
581	    const auto& d1 = bus.ops[*cmd_idx - 1];
582	    CHECK(d0.reg == kData0);
583	    CHECK(d0.value == uint32_t(val & 0xFFFFFFFFu));
584	    CHECK(d1.reg == kData1);
585	    CHECK(d1.value == uint32_t(val >> 32));
586	  }
587	}
